def predict(board_lines, action):
    if not action.startswith("MOUSE"):
        return board_lines

    try:
        parts = action.split("(")[1].split(")")
        kv_parts = parts[0].split(",")
        r = int(kv_parts[0].split("=")[1])
        c = int(kv_parts[1].split("=")[1])
    except:
        return board_lines

    grid = [list(line) for line in board_lines]

    # Define interactive blocks (top-left corner of 6x6 area)
    # Based on observed toggles and symmetric structures in the board
    interactive_blocks = [
        # Row group 14-19
        (14, 20), (14, 28), (14, 36),
        # Row group 22-27
        (22, 20), (22, 28), (22, 36),
        # Row group 30-35
        (30, 20), (30, 28), (30, 36),
        # Row group 46-51
        (46, 20), (46, 28), (46, 36),
        # Potential other blocks seen in move descriptions (even if not clicked directly in stable phase)
        # Rows 2-7, Cols 4-9, 20-25, 38-43, 54-59
        (2, 4), (2, 20), (2, 38), (2, 54),
        # Rows 10-15, Cols 4-9, 20-25, 38-43, 54-59
        (10, 4), (10, 20), (10, 38), (10, 54),
    ]

    toggled = False
    for br, bc in interactive_blocks:
        if br <= r < br + 6 and bc <= c < bc + 6:
            color = grid[br][bc]
            new_color = None
            if color == 'b':
                new_color = 'O'
            elif color == 'O':
                new_color = 'b'

            if new_color:
                for i in range(br, br+6):
                    for j in range(bc, bc+6):
                        grid[i][j] = new_color
                toggled = True
                break

    if toggled:
        score_row = grid[63]
        count = 0
        for k in range(62, -1, -1):
            if score_row[k] == 'O':
                score_row[k] = 'Y'
                count += 1
                if count >= 2:
                    break

    return ["".join(row) for row in grid]
